package com.hfr.packet.builder;
import com.hfr.builder.*;import com.hfr.entity.EntityFactionBuilder;import com.hfr.schematic.*;import com.hfr.tileentity.machine.TileEntityMachineBuilder;import com.hfr.blocks.ModBlocks;import com.hfr.main.MainRegistry;import cpw.mods.fml.common.network.internal.FMLNetworkHandler;import cpw.mods.fml.common.network.ByteBufUtils;import cpw.mods.fml.common.network.simpleimpl.*;import io.netty.buffer.ByteBuf;import net.minecraft.entity.player.EntityPlayerMP;import net.minecraft.tileentity.TileEntity;import net.minecraft.util.ChatComponentText;
public class BuilderActionPacket implements IMessage {public static final int PAUSE=0,RESUME=1,CANCEL=2,RECALL=3,START=4,REMOVE=5,UP=6,DOWN=7,OPEN_DEPOT=8;public int dimension,x,y,z,action,a,b,c,rotation;public boolean mirror;public String schematic="";public BuilderActionPacket(){}public BuilderActionPacket(TileEntityMachineBuilder d,int action){dimension=d.getWorldObj().provider.dimensionId;x=d.xCoord;y=d.yCoord;z=d.zCoord;this.action=action;}public void fromBytes(ByteBuf q){dimension=q.readInt();x=q.readInt();y=q.readInt();z=q.readInt();action=q.readByte();a=q.readInt();b=q.readInt();c=q.readInt();rotation=q.readByte();mirror=q.readBoolean();schematic=ByteBufUtils.readUTF8String(q);}public void toBytes(ByteBuf q){q.writeInt(dimension);q.writeInt(x);q.writeInt(y);q.writeInt(z);q.writeByte(action);q.writeInt(a);q.writeInt(b);q.writeInt(c);q.writeByte(rotation);q.writeBoolean(mirror);ByteBufUtils.writeUTF8String(q,schematic);}public static class Handler implements IMessageHandler<BuilderActionPacket,IMessage>{public IMessage onMessage(BuilderActionPacket m,MessageContext ctx){EntityPlayerMP p=ctx.getServerHandler().playerEntity;if(p==null||p.dimension!=m.dimension)return null;TileEntity te=p.worldObj.getTileEntity(m.x,m.y,m.z);if(!(te instanceof TileEntityMachineBuilder))return null;TileEntityMachineBuilder d=(TileEntityMachineBuilder)te;if(!BuilderDepotService.mayBuild(p,d))return null;BuilderJobData data=BuilderJobData.get(p.worldObj);BuilderJob job=data==null?null:data.get(d.getActiveJobId());EntityFactionBuilder entity=d.getLoadedBuilder();boolean nearDepot=p.getDistanceSq(m.x+.5,m.y+.5,m.z+.5)<=64;boolean nearBuilder=entity!=null&&p.getDistanceSqToEntity(entity)<=64;if(!nearDepot&&!nearBuilder)return null;if((m.action==START||m.action==REMOVE||m.action==UP||m.action==DOWN||m.action==OPEN_DEPOT)&&!nearDepot)return null;if(m.action==OPEN_DEPOT){FMLNetworkHandler.openGui(p,MainRegistry.instance,ModBlocks.guiID_builder,p.worldObj,m.x,m.y,m.z);}else if(m.action==PAUSE&&job!=null){job.state=BuilderState.PAUSED;if(entity!=null)entity.pauseWork();data.markDirty();}else if(m.action==RESUME&&job!=null){Schematic sc=com.hfr.schematic.SchematicStoreData.get(p.worldObj).getSchematic(job.schematicId);String error=sc==null?"Schematic is missing.":validate(job,sc,p);if(error!=null)p.addChatMessage(new ChatComponentText(error));else{job.state=BuilderState.LOAD_JOB;if(entity!=null){entity.setJob(job.jobId);entity.resumeWork();}data.markDirty();}}else if(m.action==CANCEL&&job!=null){job.state=BuilderState.PAUSED;job.builderId=null;if(entity!=null)entity.clearJob();d.setActiveJob(null);data.markDirty();BuilderDepotService.advance(d);}else if(m.action==RECALL&&entity!=null)entity.recallToDepot();else if(m.action==START){BuilderPlan plan=d.getPlan();Schematic sc=SchematicLibrary.get().resolve(plan.schematicId);String error=BuilderDepotService.accept(p,d,sc,plan.originX,plan.originY,plan.originZ,plan.rotation,plan.mirrored);if(error!=null)p.addChatMessage(new ChatComponentText(error));}else if(m.action==REMOVE)d.removeQueuedJob(m.a);else if(m.action==UP)d.moveQueuedJob(m.a,-1);else if(m.action==DOWN)d.moveQueuedJob(m.a,1);return BuilderDepotSnapshotPacket.create(d);}private String validate(BuilderJob j,Schematic s,EntityPlayerMP p){for(int dx=0;dx<SchematicTransform.width(s,j.rotation);dx++)for(int dz=0;dz<SchematicTransform.length(s,j.rotation);dz++)if(!BuilderTerritory.mayChange(p.worldObj,j.originX+dx,j.originZ+dz,j.factionId,false))return "Invalid territory at "+(j.originX+dx)+", "+j.originY+", "+(j.originZ+dz);return null;}}}
